'use strict';

function serializeToYaml(obj, indent = 0) {
  const pad = '  '.repeat(indent);
  const lines = [];

  if (Array.isArray(obj)) {
    if (obj.length === 0) { return '[]'; }
    for (const item of obj) {
      if (item && typeof item === 'object' && !Array.isArray(item)) {
        const entries = Object.entries(item);
        lines.push(`${pad}- ${entries[0][0]}: ${yamlValue(entries[0][1], indent + 2)}`);
        for (let i = 1; i < entries.length; i++) {
          lines.push(`${pad}  ${entries[i][0]}: ${yamlValue(entries[i][1], indent + 2)}`);
        }
      } else {
        lines.push(`${pad}- ${yamlValue(item, indent + 1)}`);
      }
    }
    return lines.join('\n');
  }

  if (obj && typeof obj === 'object') {
    for (const [key, value] of Object.entries(obj)) {
      lines.push(`${pad}${key}: ${yamlValue(value, indent + 1)}`);
    }
    return lines.join('\n');
  }

  return String(obj);
}

function yamlValue(value, indent) {
  if (value === null || value === undefined) { return 'null'; }
  if (typeof value === 'boolean') { return String(value); }
  if (typeof value === 'number') { return String(value); }
  if (typeof value === 'string') {
    if (value.includes('\n') || value.includes(': ') || value.includes('#') || /^[{[\]|>*&!%@`]/.test(value)) {
      return `|\n${'  '.repeat(indent)}${value.replace(/\n/g, '\n' + '  '.repeat(indent))}`;
    }
    if (value === '' || /^[\s"']|[\s"']$/.test(value) || /^(true|false|null|~|\d)/.test(value)) {
      return JSON.stringify(value);
    }
    return value;
  }
  if (Array.isArray(value)) {
    if (value.length === 0) { return '[]'; }
    return '\n' + serializeToYaml(value, indent);
  }
  if (typeof value === 'object') {
    return '\n' + serializeToYaml(value, indent);
  }
  return String(value);
}

module.exports = {
  serializeToYaml,
};
